        exports=['Natural gas (transported primarily via pipeline to China; also to Russia, Iran, and Azerbaijan via gas swap agreements)', 'Synthetic gasoline and refined petroleum products', 'Urea, ammonia, and chemical fertilizers', 'Cotton yarn, textiles, and apparel', 'Raw cotton and silk fabrics', 'Electricity'],
        imports=['Heavy industrial machinery and pipeline engineering equipment', 'Steel pipes and drilling equipment', 'Transport motor vehicles (white-colored vehicles predominantly permitted in Ashgabat)', 'Agricultural equipment and harvesters (John Deere, Case IH)', 'Consumer electronics and pharmaceuticals'],
