        holidays=['Unity Day (May 22)', 'September 26 Revolution Day', 'October 14 Revolution Day', 'Evacuation Day (November 30)', 'Eid al-Fitr', 'Eid al-Adha', 'Islamic New Year', 'Prophet\'s Birthday'],
