        landmarks=['Old City of Sana\'a (ancient multi-story gingerbread tower houses)', 'Shibam Hadhramaut ("Manhattan of the Desert" mud-brick skyscrapers)', 'Dar al-Hajar (Rock Palace in Wadi Dhahr)', 'Socotra Island (Dragon\'s Blood Forest in Dixam Plateau, Detwah Lagoon)', 'Great Dam of Marib and Temple of Awwam (Sanctuary of Bilqis)', 'Historic Port of Aden and Sira Fortress', 'Zabid Historic University Town', 'Jabal an-Nabi Shu\'ayb (highest peak in Arabia)', 'Al-Saleh Mosque (Sana\'a)'],
